/// <summary>
/// The <c>METCustFreeInvoiceForm_CustInvoiceTable_Extension</c> class manages enabled or disable the bulkworkflow button.
/// </summary>
/// Added for CFR4 bulk approval AR invoice.
[ExtensionOf(formDataSourceStr(CustFreeInvoice, CustInvoiceTable))]
public final class METCustFreeInvoiceForm_CustInvoiceTable_Extension
{
}

Method.Source:
/// <summary>
/// Enable or disable the bulkworkflow button.
/// </summary>
public void selectionChanged()
{
    next selectionchanged();

    FormRun                 formRun      = this.formRun();
    FormMenuButtonControl   control      = formRun.design().controlName(formControlStr(CustFreeInvoice, METBulkWorkflowMenuButton));
    MenuItemName            menuItemName = formRun.args().menuItemName(); 

    Array   array  = this.recordsMarked();
    boolean enable = (array.lastIndex() <= 1 || menuItemName != menuItemDisplayStr(CustFreeInvoiceAssignedToMeListPage)) ? false : true;

    control.visible(enable);
}
